do $$ begin if not exists (select 1 from pg_type where typname='pickup_run_type') then create type pickup_run_type as enum ('public','select'); end if; end $$;
alter table public.pickup_runs add column if not exists run_type pickup_run_type, add column if not exists is_current boolean default true, add column if not exists fee_cents int default 0, add column if not exists admin_fee_cents int default 0, add column if not exists currency text default 'usd', add column if not exists invite_phase int default 0, add column if not exists auto_managed boolean default false;
create table if not exists public.tournaments (id uuid primary key default gen_random_uuid(), title text, slug text, is_active boolean default false, start_at timestamptz, service_region text);
create table if not exists public.tournament_captains (id uuid primary key default gen_random_uuid(), tournament_id uuid references public.tournaments(id) on delete cascade, user_id uuid, team_name text, captain_name text, status text default 'confirmed');
create table if not exists public.tournament_roster (id uuid primary key default gen_random_uuid(), captain_id uuid references public.tournament_captains(id) on delete cascade, user_id uuid, status text default 'accepted');
create table if not exists public.tournament_matches (id uuid primary key default gen_random_uuid(), tournament_id uuid references public.tournaments(id) on delete cascade, stage text default 'group', match_number int, team_a_id uuid, team_b_id uuid, score_a int, score_b int, winner_id uuid, is_bye boolean default false, scheduled_at timestamptz, started_at timestamptz, completed_at timestamptz);
